def _tencent_symbol(code: str) -> str:
    return ("sh" if code.startswith(("6", "9")) else "sz") + code


def _fund_cache_key(code: str) -> str:
    return f"fundamental:{code}"


def get_fundamental_batch(codes: List[str]) -> Dict[str, Dict]:
    """批量取股票估值（PE/PB/总市值），未命中的部分一次 HTTP 补齐。

    东财 push2 间歇性拒连（见模块头注释），腾讯 qt.gtimg.cn 单次可带多只，
    且估值口径与东财一致，故为主源。按单只 code 缓存，整池抓取的结果可被
    后续逐只查询复用；失败结果不写缓存，避免一次网络抖动让估值缺席 10 分钟。
    """
    out: Dict[str, Dict] = {}
    missing: List[str] = []
    for c in codes:
        hit = market_cache.get(_fund_cache_key(c))
        if hit is not None:
            out[c] = hit
        else:
            missing.append(c)

    if missing:
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}
        url = "http://qt.gtimg.cn/q=" + ",".join(_tencent_symbol(c) for c in missing)
        fetched: Dict[str, Dict] = {}
        for attempt in range(3):
            try:
                r = requests.get(url, headers=headers, timeout=6)
                r.encoding = "gbk"
                for line in r.text.strip().splitlines():
                    if "=" not in line or "~" not in line:
                        continue
                    code_in_line = line.split("=", 1)[0].strip()[-6:]
                    f = line.split("~")
                    if len(f) <= _TENCENT_PE_DYNAMIC:
                        continue

                    def _num(idx: int, _f=f):
                        try:
                            return round(float(_f[idx]), 2)
                        except (ValueError, IndexError):
                            return None

                    fetched[code_in_line] = {
                        "name": f[1] or _STOCK_NAME.get(code_in_line, code_in_line),
                        "PE": _num(_TENCENT_PE_TTM),
                        "PE动态": _num(_TENCENT_PE_DYNAMIC),
                        "PB": _num(_TENCENT_PB),
                        "总市值(亿)": _num(_TENCENT_MARKET_CAP),
                    }
                if fetched:
                    break
            except Exception as e:
                print(f"[数据] 估值批量获取失败(第{attempt + 1}次): {e}")
                _time.sleep(0.3)

        for c, v in fetched.items():
            market_cache.set(_fund_cache_key(c), v, 600)
            out[c] = v

    return out


def get_fundamental_data(stock_code: str) -> Dict:
    """单只股票基本面，供 fundamental_analysis 工具调用。无数据返回 {}。"""
    return get_fundamental_batch([stock_code]).get(stock_code, {})

def get_news_sentiment(keyword: str = "A股", days: int = 3) -> List[Dict]:
    """获取财经新闻（模拟情感分析数据源）"""
    try:
        df = ak.stock_news_em()
        recent = df[df["发布时间"] >= (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")]
        return recent.head(10).to_dict("records")
    except Exception as e:
        print(f"[数据] 获取新闻失败: {e}")
        return []

